import type { LanguageId } from "@/shared/types/language";
import { getInstallId } from "@/shared/services/storage/installId";

/**
 * Thin client for our own Cloudflare Worker proxy (worker/) — never
 * calls JDoodle directly. The Worker holds the real JDoodle credentials
 * and owns everything JDoodle-specific (language/versionIndex mapping,
 * the Java `class Main` → `public class Main` execution-only transform,
 * response normalization), so this client only ever sees a clean,
 * provider-agnostic shape. Swapping the upstream judge provider later
 * means redeploying the Worker, not touching this file.
 */

const WORKER_URL = import.meta.env.VITE_JUDGE_WORKER_URL as string;
const SHARED_SECRET = import.meta.env.VITE_JUDGE_SHARED_SECRET as string;

export interface JudgeRunResult {
  compileError: string | null;
  runtimeError: string | null;
  output: string | null;
  timeMs: number | null;
}

export type JudgeCallOutcome =
  | { kind: "ok"; result: JudgeRunResult }
  | { kind: "timeout" }
  | { kind: "rate-limited" }
  | { kind: "infra-error" };

export async function runCase(
  language: LanguageId,
  code: string,
  stdin: string,
  timeoutMs: number,
  sessionHash: string | null
): Promise<JudgeCallOutcome> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    // A session hash (Sybil-resistant — needs a real CSES login to
    // regenerate) is preferred; the random install ID is a fallback for
    // the rare case a session cookie couldn't be read.
    const installId = sessionHash ?? (await getInstallId());
    const res = await fetch(WORKER_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-leetify-secret": SHARED_SECRET,
        "x-leetify-install-id": installId,
      },
      body: JSON.stringify({ language, code, stdin }),
      signal: controller.signal,
    });

    if (res.status === 429) return { kind: "rate-limited" };
    if (!res.ok) return { kind: "infra-error" };

    const result = (await res.json()) as JudgeRunResult;
    return { kind: "ok", result };
  } catch {
    return controller.signal.aborted ? { kind: "timeout" } : { kind: "infra-error" };
  } finally {
    clearTimeout(timer);
  }
}
