import type {
  RunRequest,
  RunResponse,
  RunCaseResult,
  RunCaseInput,
  CaseVerdict,
} from "@/extension/messaging/types";
import { runCase, type JudgeCallOutcome } from "./judgeClient";

// Conservative — avoids bursting JDoodle's daily credit quota in one
// batch and staying a good citizen of a free-tier API.
const RUN_CONCURRENCY = 3;
const RUN_TIMEOUT_MS = 10_000;

function normalizeOutput(s: string): string {
  return s
    .split("\n")
    .map((line) => line.trimEnd())
    .join("\n")
    .replace(/\n+$/, "");
}

interface CaseVerdictDetail {
  verdict: CaseVerdict;
  actualOutput: string | null;
  stderr: string | null;
  timeMs: number | null;
  compileError: string | null;
}

function computeVerdict(outcome: JudgeCallOutcome, expectedOutput: string): CaseVerdictDetail {
  if (outcome.kind === "timeout") {
    return { verdict: "timeout", actualOutput: null, stderr: null, timeMs: null, compileError: null };
  }
  if (outcome.kind === "rate-limited" || outcome.kind === "infra-error") {
    return { verdict: "infra-error", actualOutput: null, stderr: null, timeMs: null, compileError: null };
  }

  const { result } = outcome;
  if (result.compileError !== null) {
    return {
      verdict: "compile-error",
      actualOutput: null,
      stderr: null,
      timeMs: null,
      compileError: result.compileError,
    };
  }
  if (result.runtimeError !== null) {
    return {
      verdict: "runtime-error",
      actualOutput: null,
      stderr: result.runtimeError,
      timeMs: result.timeMs,
      compileError: null,
    };
  }

  const actual = result.output ?? "";
  const passed = normalizeOutput(actual) === normalizeOutput(expectedOutput);
  return {
    verdict: passed ? "pass" : "fail",
    actualOutput: actual,
    stderr: null,
    timeMs: result.timeMs,
    compileError: null,
  };
}

async function runWithConcurrency<T, R>(
  items: T[],
  limit: number,
  fn: (item: T) => Promise<R>
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;

  async function worker() {
    while (next < items.length) {
      const current = next++;
      // Safe: current < items.length by the loop condition above.
      results[current] = await fn(items[current]!);
    }
  }

  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

async function runOneCase(
  request: RunRequest,
  testCase: RunCaseInput
): Promise<{ caseId: string; detail: CaseVerdictDetail }> {
  const outcome = await runCase(
    request.language,
    request.code,
    testCase.input,
    RUN_TIMEOUT_MS,
    request.sessionHash
  );
  return { caseId: testCase.caseId, detail: computeVerdict(outcome, testCase.expectedOutput) };
}

function toResult(caseId: string, detail: CaseVerdictDetail): RunCaseResult {
  return {
    caseId,
    verdict: detail.verdict,
    actualOutput: detail.actualOutput,
    stderr: detail.stderr,
    timeMs: detail.timeMs,
  };
}

export async function handleRunRequest(request: RunRequest): Promise<RunResponse> {
  if (request.cases.length === 0) {
    return { type: "run-test-cases-result", taskId: request.taskId, compileError: null, results: [] };
  }

  // Every case shares the same source, so a compile error on the first
  // case will identically fail on every other case — running the first
  // case alone first avoids spending concurrent judge calls (and JDoodle
  // credits) on a batch that's guaranteed to fail the same way.
  // Safe: guarded by the length check above.
  const first = await runOneCase(request, request.cases[0]!);

  if (first.detail.compileError !== null) {
    const results = request.cases.map(
      (c): RunCaseResult => ({
        caseId: c.caseId,
        verdict: "compile-error",
        actualOutput: null,
        stderr: null,
        timeMs: null,
      })
    );
    return {
      type: "run-test-cases-result",
      taskId: request.taskId,
      compileError: first.detail.compileError,
      results,
    };
  }

  const remaining = request.cases.slice(1);
  const remainingResults = await runWithConcurrency(remaining, RUN_CONCURRENCY, (c) =>
    runOneCase(request, c)
  );

  return {
    type: "run-test-cases-result",
    taskId: request.taskId,
    compileError: null,
    results: [
      toResult(first.caseId, first.detail),
      ...remainingResults.map((r) => toResult(r.caseId, r.detail)),
    ],
  };
}

export function registerRunHandler(): void {
  chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
    if (!message || (message as RunRequest).type !== "run-test-cases") return false;
    void handleRunRequest(message as RunRequest).then(sendResponse);
    return true; // keep the message channel open for the async sendResponse
  });
}
