import { storageGet, storageSet } from "@/storage/chromeStorage";

const KEY = "leetify:installId";

let cached: string | null = null;

/**
 * A random, anonymous per-install identifier — no login, no PII. Used by
 * the judge Worker to meter Run usage fairly per install rather than per
 * source IP (which conflates multiple users behind one NAT, or fails
 * against IP-rotating abuse). Generated once and persisted; the same ID
 * is reused for the life of the install.
 */
export async function getInstallId(): Promise<string> {
  if (cached) return cached;
  const stored = await storageGet<string>(KEY);
  if (stored) {
    cached = stored;
    return stored;
  }
  const id = crypto.randomUUID();
  await storageSet(KEY, id);
  cached = id;
  return id;
}
